"""Demo: the conservation law sum(in-degree) = m = sum(out-degree)."""
from __future__ import annotations
from typing import List, Set, Tuple

Edge = Tuple[int, int]

def in_degrees(n: int, edges: Set[Edge]) -> List[int]:
    deg = [0] * n
    for _u, v in edges:
        deg[v] += 1
    return deg

def out_degrees(n: int, edges: Set[Edge]) -> List[int]:
    deg = [0] * n
    for u, _v in edges:
        deg[u] += 1
    return deg

def conservation_audit(n: int, edges: Set[Edge]) -> None:
    m = len(edges)
    s_in, s_out = sum(in_degrees(n, edges)), sum(out_degrees(n, edges))
    print(f"n={n}, m={m}, sum(in)={s_in}, sum(out)={s_out}")
    assert s_in == m == s_out, "conservation law violated"
    print("verified: sum(in) = m = sum(out)")

if __name__ == "__main__":
    edges = {(0, 2), (1, 2), (0, 3), (2, 4), (3, 4), (4, 5), (1, 3)}
    conservation_audit(6, edges)

"""Demo: topological layering recovers foundations (sources) and frontier (sinks)."""
from __future__ import annotations
from collections import defaultdict
from typing import Dict, List, Optional, Set, Tuple

Edge = Tuple[int, int]

def topological_layers(n: int, edges: Set[Edge]) -> Optional[List[List[int]]]:
    succ: Dict[int, List[int]] = defaultdict(list)
    indeg = [0] * n
    for u, v in edges:
        succ[u].append(v)
        indeg[v] += 1
    remaining, frontier, layers = n, [v for v in range(n) if indeg[v] == 0], []
    while frontier:
        layers.append(sorted(frontier))
        remaining -= len(frontier)
        nxt: List[int] = []
        for u in frontier:
            for w in succ[u]:
                indeg[w] -= 1
                if indeg[w] == 0:
                    nxt.append(w)
        frontier = nxt
    return layers if remaining == 0 else None  # None <=> cycle present

if __name__ == "__main__":
    acyclic = {(0, 2), (1, 2), (0, 3), (2, 4), (3, 4), (4, 5), (1, 3)}
    print("acyclic layers:", topological_layers(6, acyclic))
    cyclic = {(0, 1), (1, 0), (2, 0)}
    print("cyclic (2-cycle):", topological_layers(3, cyclic))

