from __future__ import annotations
import math
from typing import List

def hill_exponent(degrees: List[int], k_min: int = 1) -> float:
    """Discrete maximum-likelihood estimate of gamma in P(k) ~ k^{-gamma}
    for the tail k >= k_min.  Runs in O(#degrees)."""
    tail = [k for k in degrees if k >= k_min]
    if not tail:
        return float("nan")
    s = sum(math.log(k / (k_min - 0.5)) for k in tail)
    return 1.0 + len(tail) / s
